import React, { useState } from "react";
import "bootstrap-icons/font/bootstrap-icons.css";

export default function MobileNavigationMegaMenuComponent() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [openMenus, setOpenMenus] = useState({});

  // Toggle hamburger
  const toggleMenu = () => setMenuOpen(!menuOpen);

  // Toggle accordion (works for any level)
  const toggleSubmenu = (key) => {
    setOpenMenus((prev) => ({
      ...prev,
      [key]: !prev[key],
    }));
  };

  return (
    <div className="mobile-navigations-bar header">
      <nav className="mobile-navbar">
        <div className="mobile-logo">
          <a href="https://www.accorian.com/" target="_blank" rel="noreferrer">
            <img
              src="https://www.accorian.com/wp-content/uploads/2024/10/Accorian-Logo.svg"
              alt="Accorian Logo"
            />
          </a>
        </div>
        <div className="mobile-hamburger" onClick={toggleMenu}>
          <i
            className={`bi ${menuOpen ? "bi-x" : "bi-list"}`}
            id="mobile-hamburger-icon"
          ></i>
        </div>
      </nav>

      <ul
        className="mobile-menu"
        style={{ display: menuOpen ? "flex" : "none" }}
      >
        {/* Home */}
        <li>
          <a href="https://www.accorian.com/" target="_blank" rel="noreferrer">
            Home
          </a>
        </li>

        {/* Services */}
        <li
          className={`mobile-has-submenu ${
            openMenus.services ? "mobile-open" : ""
          }`}
        >
          <a
            href="#"
            onClick={(e) => {
              e.preventDefault();
              toggleSubmenu("services");
            }}
          >
            Services
          </a>
          <ul
            className="mobile-submenu"
            style={{ display: openMenus.services ? "block" : "none" }}
          >
            {/* HITRUST */}
            <li
              className={`mobile-has-submenu ${
                openMenus.hitrust ? "mobile-open" : ""
              }`}
            >
              <a
                href="#"
                onClick={(e) => {
                  e.preventDefault();
                  toggleSubmenu("hitrust");
                }}
              >
                HITRUST®
              </a>
              <ul
                className="mobile-submenu"
                style={{ display: openMenus.hitrust ? "block" : "none" }}
              >
                <li>
                  <a
                    href="https://www.accorian.com/hitrust/"
                    target="_blank"
                    rel="noreferrer"
                  >
                    HITRUST Services
                  </a>
                </li>
                <li>
                  <a
                    href="https://www.accorian.com/hitrust-readiness/"
                    target="_blank"
                    rel="noreferrer"
                  >
                    HITRUST Readiness
                  </a>
                </li>
                <li>
                  <a
                    href="https://www.accorian.com/hitrust-assessment/"
                    target="_blank"
                    rel="noreferrer"
                  >
                    HITRUST Assessment
                  </a>
                </li>
              </ul>
            </li>

            {/* ISO */}
            <li
              className={`mobile-has-submenu ${
                openMenus.iso ? "mobile-open" : ""
              }`}
            >
              <a
                href="#"
                onClick={(e) => {
                  e.preventDefault();
                  toggleSubmenu("iso");
                }}
              >
                ISO Certifications
              </a>
              <ul
                className="mobile-submenu"
                style={{ display: openMenus.iso ? "block" : "none" }}
              >
                <li>
                  <a
                    href="https://www.accorian.com/iso-certifications/"
                    target="_blank"
                    rel="noreferrer"
                  >
                    ISO Assessments
                  </a>
                </li>
                <li>
                  <a
                    href="https://www.accorian.com/iso-27001/"
                    target="_blank"
                    rel="noreferrer"
                  >
                    ISO 27001
                  </a>
                </li>
              </ul>
            </li>

            {/* Add more service categories here (PCI, SOC, NIST, etc.) */}
          </ul>
        </li>

        {/* Other Main Links */}
        <li>
          <a
            href="https://www.accorian.com/securing-ai/"
            target="_blank"
            rel="noreferrer"
          >
            Securing AI
          </a>
        </li>
        <li>
          <a
            href="https://www.accorian.com/contact-us/"
            target="_blank"
            rel="noreferrer"
          >
            Contact Us
          </a>
        </li>
      </ul>
    </div>
  );
}
